package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="shared_group_invitations") @Data @NoArgsConstructor @AllArgsConstructor @Builder
public class SharedGroupInvitation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="group_id",nullable=false) private SharedExpenseGroup group; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="invited_by_user_id",nullable=false) private User invitedBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="invited_user_id") private User invitedUser; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="member_id") private SharedGroupMember member; private String email; private String mobile; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private SharedInvitationStatus status=SharedInvitationStatus.PENDING; @Builder.Default @Column(nullable=false,updatable=false) private LocalDateTime createdAt=LocalDateTime.now(); @Builder.Default @Column(nullable=false) private LocalDateTime expiresAt=LocalDateTime.now().plusDays(30); private LocalDateTime respondedAt; }
